CREATE TABLE listing_reports (id BIGSERIAL PRIMARY KEY, reporter_id BIGINT NOT NULL REFERENCES accounts(id), listing_id BIGINT NOT NULL REFERENCES listings(id), reason VARCHAR(80) NOT NULL, details VARCHAR(1200), status VARCHAR(20) NOT NULL DEFAULT 'OPEN', created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE conversations (id BIGSERIAL PRIMARY KEY, tenant_id BIGINT NOT NULL REFERENCES accounts(id), owner_id BIGINT NOT NULL REFERENCES accounts(id), listing_id BIGINT NOT NULL REFERENCES listings(id), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), CONSTRAINT conversation_once UNIQUE(tenant_id,listing_id));
CREATE TABLE messages (id BIGSERIAL PRIMARY KEY, conversation_id BIGINT NOT NULL REFERENCES conversations(id) ON DELETE CASCADE, sender_id BIGINT NOT NULL REFERENCES accounts(id), body VARCHAR(2000) NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE notifications (id BIGSERIAL PRIMARY KEY, recipient_id BIGINT NOT NULL REFERENCES accounts(id) ON DELETE CASCADE, title VARCHAR(180) NOT NULL, body VARCHAR(500) NOT NULL, href VARCHAR(500), read BOOLEAN NOT NULL DEFAULT FALSE, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX notification_recipient_idx ON notifications(recipient_id, created_at DESC); CREATE INDEX messages_conversation_idx ON messages(conversation_id, created_at);
